//! Frozen pre-split wake SQL, exercised only by the parity oracle.
use crate::agent_tables::AgentsStorageRow;
use crate::peer_update_settings::Canvas;
use studio_db_api::DbQuery;
use studio_runtime_schema::persistence::HoldStatus;

#[derive(DbQuery)]
#[db_query(database=Canvas,mode=read,cardinality=optional,native,result=String,tables(agents=AgentsStorageRow),sql=r#"SELECT a.id FROM {agents} AS a INDEXED BY runtime_agent_account_wake_candidates_v7 WHERE a.deleted_at IS NULL AND COALESCE(a.remote_worker,0)=0 AND COALESCE(a.remote_anchor,0)=0 AND a.hold_status=?1 AND ((((((SELECT status FROM chats WHERE id=a.id)='queued' AND EXISTS(SELECT 1 FROM chats ch WHERE ch.id=a.id AND ch.auto_wake=1) AND NOT EXISTS(SELECT 1 FROM turns WHERE chat=a.id AND state IN ('starting','running')) AND COALESCE(a.native_failure_hold,0)=0) AND EXISTS(SELECT 1 FROM runtime_events e WHERE e.agent=a.id AND e.epoch=json_extract(a.record,'$.epoch') AND e.status='pending' AND NOT (e.kind='child_result' AND e.created>?2 AND EXISTS(SELECT 1 FROM runtime_agents c WHERE c.parent_id=+e.agent AND c.deleted_at IS NULL AND (SELECT status FROM chats WHERE id=c.id) IN ('queued','starting','running'))))) OR (((SELECT status FROM chats WHERE id=a.id)='running' AND (SELECT provider_turn FROM turns WHERE chat=a.id AND state IN ('starting','running') LIMIT 1) IS NOT NULL AND COALESCE(a.steer_rejected_turn_id,'')<>(SELECT provider_turn FROM turns WHERE chat=a.id AND state IN ('starting','running') LIMIT 1) AND COALESCE(a.native_failure_hold,0)=0 AND EXISTS(SELECT 1 FROM turns WHERE chat=a.id AND state IN ('starting','running')) AND EXISTS(SELECT 1 FROM chats ch WHERE ch.id=a.id AND ch.auto_wake=1) AND NOT EXISTS(SELECT 1 FROM chats ch WHERE ch.id=a.id AND ch.execution_mode='vm')) AND EXISTS(SELECT 1 FROM runtime_events e WHERE e.agent=a.id AND e.epoch=json_extract(a.record,'$.epoch') AND e.status='pending' AND e.kind NOT IN ('radio','radio_turn','chat_review'))) OR (((SELECT status FROM chats WHERE id=a.id)='queued' AND EXISTS(SELECT 1 FROM chats ch WHERE ch.id=a.id AND ch.auto_wake=1) AND NOT EXISTS(SELECT 1 FROM turns WHERE chat=a.id AND state IN ('starting','running')) AND COALESCE(a.native_failure_hold,0)=0) AND json_extract(a.record,'$.nativeReview.status')='pending'))) OR (((a.provider='codex' AND EXISTS(SELECT 1 FROM turns t WHERE t.chat=a.id AND t.attempt_submitted=1 AND t.attempt_connection_generation IS NOT NULL) AND (SELECT status FROM chats WHERE id=a.id) IN ('starting','running','waiting','paused','interrupted')) OR (a.has_disconnect_recovery=1 AND ( COALESCE((SELECT status FROM chats WHERE id=a.id),'') NOT IN ('completed','waiting','paused','parked') OR a.disconnect_recovery_stage IS NOT NULL)) OR (a.has_restart_recovery=1 AND ( COALESCE((SELECT status FROM chats WHERE id=a.id),'') NOT IN ('completed','waiting','paused','parked') OR COALESCE(a.restart_recovery_stage,'') NOT IN ('finished','continued','reattached','input_restored')))))) AND (a.account_key='' OR json_type(a.record,'$.accountKey') NOT IN ('null','text')) LIMIT 1"#)]
pub(super) struct Invalid {
    #[db(column=AgentsStorageRow::HOLD_STATUS)]
    pub hold: HoldStatus,
    #[db(column=crate::queue_schema::EventsRow::CREATED)]
    pub held_after: f64,
}

#[derive(DbQuery)]
#[db_query(database=Canvas,mode=read,cardinality=many,native,result=String,tables(agents=AgentsStorageRow),sql=r#"SELECT DISTINCT a.account_key FROM {agents} AS a INDEXED BY runtime_agent_account_wake_candidates_v7 WHERE a.deleted_at IS NULL AND COALESCE(a.remote_worker,0)=0 AND COALESCE(a.remote_anchor,0)=0 AND a.hold_status=?1 AND ((((((SELECT status FROM chats WHERE id=a.id)='queued' AND EXISTS(SELECT 1 FROM chats ch WHERE ch.id=a.id AND ch.auto_wake=1) AND NOT EXISTS(SELECT 1 FROM turns WHERE chat=a.id AND state IN ('starting','running')) AND COALESCE(a.native_failure_hold,0)=0) AND EXISTS(SELECT 1 FROM runtime_events e WHERE e.agent=a.id AND e.epoch=json_extract(a.record,'$.epoch') AND e.status='pending' AND NOT (e.kind='child_result' AND e.created>?4 AND EXISTS(SELECT 1 FROM runtime_agents c WHERE c.parent_id=+e.agent AND c.deleted_at IS NULL AND (SELECT status FROM chats WHERE id=c.id) IN ('queued','starting','running'))))) OR (((SELECT status FROM chats WHERE id=a.id)='running' AND (SELECT provider_turn FROM turns WHERE chat=a.id AND state IN ('starting','running') LIMIT 1) IS NOT NULL AND COALESCE(a.steer_rejected_turn_id,'')<>(SELECT provider_turn FROM turns WHERE chat=a.id AND state IN ('starting','running') LIMIT 1) AND COALESCE(a.native_failure_hold,0)=0 AND EXISTS(SELECT 1 FROM turns WHERE chat=a.id AND state IN ('starting','running')) AND EXISTS(SELECT 1 FROM chats ch WHERE ch.id=a.id AND ch.auto_wake=1) AND NOT EXISTS(SELECT 1 FROM chats ch WHERE ch.id=a.id AND ch.execution_mode='vm')) AND EXISTS(SELECT 1 FROM runtime_events e WHERE e.agent=a.id AND e.epoch=json_extract(a.record,'$.epoch') AND e.status='pending' AND e.kind NOT IN ('radio','radio_turn','chat_review'))) OR (((SELECT status FROM chats WHERE id=a.id)='queued' AND EXISTS(SELECT 1 FROM chats ch WHERE ch.id=a.id AND ch.auto_wake=1) AND NOT EXISTS(SELECT 1 FROM turns WHERE chat=a.id AND state IN ('starting','running')) AND COALESCE(a.native_failure_hold,0)=0) AND json_extract(a.record,'$.nativeReview.status')='pending'))) OR (((a.provider='codex' AND EXISTS(SELECT 1 FROM turns t WHERE t.chat=a.id AND t.attempt_submitted=1 AND t.attempt_connection_generation IS NOT NULL) AND (SELECT status FROM chats WHERE id=a.id) IN ('starting','running','waiting','paused','interrupted')) OR (a.has_disconnect_recovery=1 AND ( COALESCE((SELECT status FROM chats WHERE id=a.id),'') NOT IN ('completed','waiting','paused','parked') OR a.disconnect_recovery_stage IS NOT NULL)) OR (a.has_restart_recovery=1 AND ( COALESCE((SELECT status FROM chats WHERE id=a.id),'') NOT IN ('completed','waiting','paused','parked') OR COALESCE(a.restart_recovery_stage,'') NOT IN ('finished','continued','reattached','input_restored')))))) AND a.account_key>?2 ORDER BY a.account_key LIMIT ?3"#)]
pub(super) struct Accounts<'a> {
    #[db(column=AgentsStorageRow::HOLD_STATUS)]
    pub hold: HoldStatus,
    #[db(column=AgentsStorageRow::ACCOUNT_KEY)]
    pub after: &'a str,
    #[db(column=AgentsStorageRow::ROWID)]
    pub limit: i64,
    #[db(column=crate::queue_schema::EventsRow::CREATED)]
    pub held_after: f64,
}

